def solve(tokens):
    """Evaluate Reverse Polish Notation with +, -, *, /.
    Division truncates toward zero (like in many languages).
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division truncating toward zero
                # Use integer division with truncation toward zero.
                # Python's // floors toward -inf, so adjust for sign.
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                res = abs(a) // abs(b)
                if (a < 0) ^ (b < 0):
                    res = -res
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

