        if not isinstance(seq, (list, tuple)):
            try:
                # Strings are iterable but not intended; treat as empty.
                if isinstance(seq, str):
                    seq = []
                else:
                    seq = list(seq)
            except Exception:
                seq = []
    else:
        seq = list(args)
    # Ensure seq is a list of numbers
    if not seq:
        return 0
    import bisect
    tails = []
    for x in seq:
        # Skip non-numeric values gracefully
        try:
            val = x
        except Exception:
            continue
        idx = bisect.bisect_left(tails, val)
        if idx == len(tails):
            tails.append(val)
