def solve(grid):
    """Count islands (connected components of 1s) in a possibly ragged grid.
    Cells connect up, down, left, right. Handles empty grid and non‑rectangular rows.
    """
    if not grid:
        return 0
    rows = len(grid)
    # Use a set for visited coordinates to handle ragged rows safely.
    visited = set()
    def neighbors(r, c):
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                yield nr, nc
    def bfs(start_r, start_c):
        stack = [(start_r, start_c)]
        visited.add((start_r, start_c))
        while stack:
            r, c = stack.pop()
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited and grid[nr][nc] == 1:
                    visited.add((nr, nc))
                    stack.append((nr, nc))
    count = 0
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == 1 and (r, c) not in visited:
                bfs(r, c)
                count += 1
    return count

