    else:
        tokens = list(args)
    stack = []
    pairs = {')': '(', '}': '{', ']': '['}
    opening = set(pairs.values())
    for ch in tokens:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
