def solve(grid):
    """Count islands in a grid.
    Handles empty grid and ragged rows. Islands are groups of 1s connected
    vertically or horizontally.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def get(i, j):
        if i < 0 or i >= rows:
            return 0
        if j < 0 or j >= len(grid[i]):
            return 0
        return grid[i][j]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            if get(x, y) != 1:
                continue
            visited.add((x, y))
            stack.extend([(x-1, y), (x+1, y), (x, y-1), (x, y+1)])
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if get(i, j) == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

